const enc=new TextEncoder();
async function mac(secret,text){const key=await crypto.subtle.importKey('raw',enc.encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign']);return [...new Uint8Array(await crypto.subtle.sign('HMAC',key,enc.encode(text)))].map(n=>n.toString(16).padStart(2,'0')).join('')}
async function isAdmin(req,env){if(!env.ADMIN_PIN||!env.SESSION_SECRET)return false;let token=(req.headers.get('Cookie')||'').match(/(?:^|; )lemon_admin=([^;]+)/)?.[1];if(!token)return false;let [expires,sig]=token.split('.');return Number(expires)>Date.now()&&sig===await mac(env.SESSION_SECRET,expires)}

export default {async fetch(req,env){let url=new URL(req.url);try{
if(url.pathname.startsWith('/api/')&&req.method==='POST'&&req.headers.get('Origin')!==url.origin)return Response.json({error:'Invalid origin'},{status:403});
if(url.pathname==='/api/login'&&req.method==='POST'){
 if(!env.ADMIN_PIN||!env.SESSION_SECRET)return Response.json({error:'Admin is not configured on this deployment.'},{status:503});
 const b=await req.json();if(b.pin!==env.ADMIN_PIN){await new Promise(r=>setTimeout(r,700));return Response.json({error:'Incorrect PIN'},{status:401})}
 const expires=String(Date.now()+8*60*60*1000);return Response.json({ok:true},{headers:{'Set-Cookie':'lemon_admin='+expires+'.'+await mac(env.SESSION_SECRET,expires)+'; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=28800'}})
}
if(url.pathname==='/api/logout')return Response.json({ok:true},{headers:{'Set-Cookie':'lemon_admin=; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=0'}});
if(url.pathname==='/api/admin'){
 if(!await isAdmin(req,env))return Response.json({error:'Unlock admin first'},{status:401});
 if(req.method==='GET'){const r=await env.DB.prepare('SELECT value FROM app_settings WHERE id=?').bind('admin').first();return Response.json(r?JSON.parse(r.value):{expenses:[],team:[]},{headers:{'Cache-Control':'no-store'}})}
 if(req.method==='POST'){const b=await req.json();if(!Array.isArray(b.expenses)||!Array.isArray(b.team)||b.expenses.length>200||b.team.length<1||b.team.length>100||JSON.stringify(b).length>100000||b.expenses.some(x=>typeof x.name!=='string'||!Number.isFinite(x.amount)||x.amount<0||(x.gst!==undefined&&(!Number.isFinite(x.gst)||x.gst<0)))||b.team.some(x=>typeof x.name!=='string'||!x.name.trim()||x.name.length>50)||new Set(b.team.map(x=>x.name.trim().toLowerCase())).size!==b.team.length)return Response.json({error:'Invalid details'},{status:400});await env.DB.prepare('INSERT INTO app_settings(id,value) VALUES(?,?) ON CONFLICT(id) DO UPDATE SET value=excluded.value').bind('admin',JSON.stringify(b)).run();return Response.json({ok:true})}
}
if(url.pathname==='/api/team'&&req.method==='GET'){const row=await env.DB.prepare('SELECT value FROM app_settings WHERE id=?').bind('admin').first();const team=row?JSON.parse(row.value).team:[];return Response.json(team.length?team.map(x=>x.name):sellers)}
if(url.pathname==='/api/sales'){
if(req.method==='GET'){const r=await env.DB.prepare('SELECT * FROM sales WHERE voided=0 ORDER BY created_at DESC LIMIT 10000').all();return Response.json(r.results,{headers:{'Cache-Control':'no-store'}})}
if(req.method==='POST'){let b=await req.json();const config=await env.DB.prepare('SELECT value FROM app_settings WHERE id=?').bind('admin').first();const activeTeam=config?JSON.parse(config.value).team:[];const crew=activeTeam.length?activeTeam.map(x=>x.name):sellers;if(!crew.includes(b.seller)||!['Cash','Transfer'].includes(b.payment)||!Array.isArray(b.items)||b.items.length!==3||b.items.some(n=>!Number.isInteger(n)||n<0||n>100)||!b.items.some(Boolean)||![0,10].includes(b.discount)||typeof b.id!=='string'||b.id.length>60)return Response.json({error:'Invalid sale'},{status:400});let cups=b.items.reduce((a,v)=>a+v,0),total=b.items.reduce((a,v,i)=>a+v*(prices[i]-b.discount),0);await env.DB.prepare('INSERT OR IGNORE INTO sales(id,seller,items,cups,total,payment,created_at) VALUES(?,?,?,?,?,?,?)').bind(b.id,b.seller,JSON.stringify(b.items),cups,total,b.payment,new Date().toISOString()).run();return Response.json({ok:true})}
}
if(url.pathname==='/api/void'&&req.method==='POST'){if(!await isAdmin(req,env))return Response.json({error:'Unlock admin to undo a sale'},{status:401});let b=await req.json();await env.DB.prepare('UPDATE sales SET voided=1 WHERE id=?').bind(b.id).run();return Response.json({ok:true})}
if(url.pathname!=='/')return new Response('Not found',{status:404});return new Response(html,{headers:{'Content-Type':'text/html; charset=utf-8'}})
}catch(e){return Response.json({error:'Could not sync. Please try again.'},{status:503})}}};
